// Per-crop source records are loaded on demand so a visit only downloads the open crop.
// Generated by scripts/split_crop_data.py from the combined source snapshots.
type Protection = {
  name: string;
  geography: string;
  impact: string;
  modes: string[];
  type: string;
  passage: string;
};
export type CropPayload = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  records: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  district: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  production: any[];
  sources: { protection: Protection[] };
};
const files = import.meta.glob<{ default: CropPayload }>("./crops/*.json");
const cache = new Map<string, CropPayload>();
const pending = new Map<string, Promise<CropPayload | undefined>>();

export function loadCropData(crop: string): Promise<CropPayload | undefined> {
  const ready = cache.get(crop);
  if (ready) return Promise.resolve(ready);
  const existing = pending.get(crop);
  if (existing) return existing;
  const loader = files[`./crops/${crop}.json`];
  if (!loader) return Promise.resolve(undefined);
  const promise = loader().then((m) => {
    cache.set(crop, m.default);
    return m.default;
  });
  pending.set(crop, promise);
  return promise;
}
export const loadAllCropData = () =>
  Promise.all(Object.keys(files).map((f) => loadCropData(f.slice(8, -5))));
export function cropData(crop: string): CropPayload {
  const data = cache.get(crop);
  if (!data) throw new Error(`Crop records for ${crop} are not loaded yet.`);
  return data;
}
export const isCropDataLoaded = (crop: string) => cache.has(crop);
/** Seeds the cache from route loader data so hydrated pages render without refetching. */
export function primeCropData(crop: string, data: CropPayload | undefined) {
  if (data && !cache.has(crop)) cache.set(crop, data);
}
